uv run python - <<'PY'
import numpy as np, pandas as pd
train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(int)
classes = np.unique(y)

def acc(a,b): return float((a==b).mean())

def zscore(train_x, test_x):
    mu=train_x.mean(axis=0)
    sd=train_x.std(axis=0)
    sd[sd==0]=1.0
    return (train_x-mu)/sd, (test_x-mu)/sd

def loocv_ridge(ridge=100.0, standardize=False):
    preds=[]
    for i in range(len(X)):
        Xt=np.delete(X,i,axis=0); yt=np.delete(y,i); xv=X[i:i+1]
        if standardize:
            Xt, xv = zscore(Xt, xv)
        Xt1=np.c_[np.ones(len(Xt)), Xt]
        xv1=np.c_[np.ones(len(xv)), xv]
        reg=np.eye(Xt1.shape[1]); reg[0,0]=0
        beta=np.linalg.solve(Xt1.T@Xt1 + ridge*reg, Xt1.T@yt)
        preds.append(int((xv1@beta)[0] >= 0.5))
    return acc(np.array(preds), y)

def loocv_logreg(l2=1.0, lr=0.1, steps=300, standardize=False):
    preds=[]
    for i in range(len(X)):
        Xt=np.delete(X,i,axis=0); yt=np.delete(y,i); xv=X[i:i+1]
        if standardize:
            Xt, xv = zscore(Xt, xv)
        w=np.zeros(Xt.shape[1])
        b=0.0
        for _ in range(steps):
            z=Xt@w+b
            p=1/(1+np.exp(-np.clip(z,-30,30)))
            grad_w = Xt.T@(p-yt)/len(Xt) + l2*w/len(Xt)
            grad_b = np.mean(p-yt)
            w -= lr*grad_w
            b -= lr*grad_b
        pv=1/(1+np.exp(-np.clip(xv@w+b,-30,30)))[0]
        preds.append(int(pv>=0.5))
    return acc(np.array(preds), y)

for std in [False, True]:
    for r in [10,30,100,300,1000]:
        print('ridge', std, r, loocv_ridge(r, std))
for std in [False, True]:
    for l2 in [0.01,0.1,1,10,100]:
        print('logreg', std, l2, loocv_logreg(l2=l2, lr=0.2, steps=500, standardize=std))
